import{PARTS,DEFAULT,cloneState,values,compose,randomState,readFavorites,writeFavorites,copyText}from'./model.js';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];let state=cloneState(DEFAULT),part='ears',filter='全部小狗',counter=1,toastTimer;let storage;try{storage=localStorage}catch{}let favorites=readFavorites(storage);let gallery=[];const categories=['全部小狗','垂耳小狗','软团小狗','开心','撒娇','困困','委屈'];
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}function button(cls,text,fn){const b=el('button',cls,text);b.type='button';b.addEventListener('click',fn);return b}function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
const hasSaved=s=>favorites.some(x=>compose(x)===compose(s));
function save(s){const t=compose(s),next=hasSaved(s)?favorites.filter(x=>compose(x)!==t):[cloneState(s),...favorites];if(next.length>500){toast('小狗窝已经住满 500 只啦');return}if(!writeFavorites(storage,next)){toast('浏览器无法保存收藏，请允许本地存储后再试');return}const added=next.length>favorites.length;favorites=next;renderSaved();renderGallery();renderFavorites();toast(added?'♡ 小狗住进收藏夹啦':'已从收藏中移出')}
async function copy(s){const text=compose(s);const method=await copyText(text,navigator,document);if(method==='manual'){$('#copy-text').value=text;$('#manual-copy').showModal();$('#copy-text').focus();$('#copy-text').select()}else toast('复制好啦！把小狗带去聊天吧 ♡')}
function renderSaved(){$('#favorite-count').textContent=favorites.length;$('#save').setAttribute('aria-pressed',String(hasSaved(state)));$('#save').textContent=hasSaved(state)?'♥ 已收藏':'♡ 收藏';$$('.nav-item').forEach(b=>{if(b.dataset.view==='favorites')b.setAttribute('aria-label',`我的收藏，${favorites.length}只小狗`)})}
function render(){const text=compose(state);$('#puppy').textContent=text;$('#puppy').style.fontSize=Array.from(text).length>27?'clamp(19px, 3vw, 29px)':'';$('#recipe').textContent=['ears','eyes','mouth','decor'].map(k=>PARTS[k][state[k]].name).join(' / ')+(Object.keys(state.custom).length?' · 自定义':'');$('#puppy-caption').textContent=Object.keys(state.custom).length?'这一只，是你的独家小狗':PARTS.eyes[state.eyes].mood==='困困'?'小狗困困，陪你慢慢休息':'刚出炉的软乎乎小狗';$('#puppy-number').textContent=String(counter).padStart(3,'0');renderFamilies();renderChoices();renderSaved()}
function renderFamilies(){const host=$('#families');host.replaceChildren();[['classic','U・ﻌ・U','垂耳小狗'],['soft','૮₍ ˶• ﻌ •˶ ₎ა','软团小狗']].forEach(([family,face,name])=>{const b=button('family-option','',()=>{state={ears:family==='classic'?0:1,eyes:family==='classic'?1:0,mouth:0,decor:family==='classic'?0:1,custom:{}};counter++;render();renderCustom()});b.setAttribute('aria-pressed',String(PARTS.ears[state.ears].family===family));b.append(el('span','kaomoji',face),el('small','',name));host.append(b)})}
function sample(k,x){if(k==='ears')return x.v[0]+'◦'+x.v[1];if(k==='eyes')return x.v[0]+' '+x.v[1];if(k==='mouth')return x.v;return x.v.join('')||'—'}
const customKeys={ears:['left','right'],eyes:['eyeLeft','eyeRight'],mouth:['mouth'],decor:['prefix','suffix']};
function renderChoices(){const labels={ears:'软软的耳朵',eyes:'眼睛里藏着小情绪',mouth:'嘴巴也在说喜欢你',decor:'加一点点可爱'};$('#part-title').textContent=labels[part];$('#part-count').textContent=PARTS[part].length+' 个小零件';const host=$('#choices');host.replaceChildren();PARTS[part].forEach((x,i)=>{const b=button('choice','',()=>{state[part]=i;customKeys[part].forEach(k=>delete state.custom[k]);render();renderCustom()});b.setAttribute('aria-label',x.name);b.setAttribute('aria-pressed',String(state[part]===i&&!customKeys[part].some(k=>Object.hasOwn(state.custom,k))));b.append(el('span','kaomoji',sample(part,x)),el('small','',x.name));host.append(b)})}
function setPart(next,focus=false){part=next;$$('[data-part]').forEach(b=>{const selected=b.dataset.part===part;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected&&focus)b.focus()});$('#part-panel').setAttribute('aria-labelledby','tab-'+part);renderChoices();renderCustom()}
const names={left:'左耳',right:'右耳',eyeLeft:'左眼',eyeRight:'右眼',mouth:'嘴巴',prefix:'前面的小装饰',suffix:'后面的小装饰'};
function renderCustom(){const host=$('#custom-fields');host.replaceChildren();const v=values(state);customKeys[part].forEach(k=>{const label=el('label','',names[k]);const input=el('input');input.type='text';input.dir='ltr';input.value=v[k];input.setAttribute('aria-label',names[k]+'自定义');input.autocomplete='off';input.spellcheck=false;input.addEventListener('input',()=>{const clean=Array.from(input.value.replace(/[\u0000-\u001f\u007f\u202a-\u202e\u2066-\u2069]/gu,'')).slice(0,16).join('');state.custom[k]=clean;render()});label.append(input);host.append(label)})}
function card(s){const text=compose(s),saved=hasSaved(s);const c=el('article','puppy-card');const top=el('div','card-portrait');const saveBtn=button('card-save',saved?'♥':'♡',()=>save(s));saveBtn.setAttribute('aria-label',(saved?'取消收藏 ':'收藏 ')+text);saveBtn.setAttribute('aria-pressed',String(saved));const face=el('span','kaomoji card-puppy',text);face.dir='ltr';if(Array.from(text).length>25)face.style.fontSize='16px';top.append(face,saveBtn);const bottom=el('div','card-bottom');const name=el('span','card-name',PARTS.eyes[s.eyes].mood+'小狗');name.append(el('small','',PARTS.ears[s.ears].family==='classic'?'垂耳系':'软团系'));const actions=el('div','card-actions');actions.append(button('','捏捏',()=>{state=cloneState(s);counter++;showView('studio');render();renderCustom();$('.workbench').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}),button('','复制',()=>copy(s)));bottom.append(name,actions);c.append(top,bottom);return c}
function matches(s){return filter==='全部小狗'||filter==='垂耳小狗'&&PARTS.ears[s.ears].family==='classic'||filter==='软团小狗'&&PARTS.ears[s.ears].family==='soft'||PARTS.eyes[s.eyes].mood===filter}
function renderGallery(){const host=$('#gallery');host.replaceChildren(...gallery.filter(matches).slice(0,12).map(card))}
function refreshGallery(){gallery=[cloneState(DEFAULT),{ears:0,eyes:1,mouth:0,decor:0,custom:{}},...['开心','撒娇','困困','委屈'].flatMap(mood=>Array.from({length:8},(_,i)=>randomState(i%2?'classic':'soft',mood)))];const family=filter==='垂耳小狗'?'classic':filter==='软团小狗'?'soft':null;const mood=['开心','撒娇','困困','委屈'].includes(filter)?filter:null;for(let i=0;i<12;i++)gallery.push(randomState(family,mood));const seen=new Set();gallery=gallery.filter(s=>{const t=compose(s);if(seen.has(t))return false;seen.add(t);return true});renderGallery()}
function renderFilters(){const host=$('#filters');host.replaceChildren();categories.forEach(name=>{const b=button('filter',name,()=>{filter=name;renderFilters();refreshGallery()});b.setAttribute('aria-pressed',String(filter===name));host.append(b)})}
function renderFavorites(){$('#favorite-grid').replaceChildren(...favorites.map(card));$('#empty-favorites').hidden=!!favorites.length}
function showView(view){$('#studio').hidden=view!=='studio';$('#favorites').hidden=view!=='favorites';$$('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(view==='favorites')renderFavorites()}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));$('.brand').addEventListener('click',e=>{e.preventDefault();showView('studio');window.scrollTo({top:0,behavior:'smooth'})});$$('[data-part]').forEach(b=>{b.addEventListener('click',()=>setPart(b.dataset.part));b.addEventListener('keydown',e=>{const keys=['ears','eyes','mouth','decor'];let i=keys.indexOf(part);if(e.key==='ArrowRight')i=(i+1)%4;else if(e.key==='ArrowLeft')i=(i+3)%4;else if(e.key==='Home')i=0;else if(e.key==='End')i=3;else return;e.preventDefault();setPart(keys[i],true)})});$('#copy').addEventListener('click',()=>copy(state));$('#save').addEventListener('click',()=>save(state));$('#random').addEventListener('click',()=>{state=randomState();counter++;render();renderCustom();toast('叮！一只新小狗诞生了')});$('#reset').addEventListener('click',()=>{state=cloneState(DEFAULT);render();renderCustom();toast('小狗恢复出厂可爱啦')});$('#more').addEventListener('click',()=>{refreshGallery();toast('新的一窝小狗来啦')});$('#custom-toggle').addEventListener('click',()=>{const open=$('#custom-fields').hidden;$('#custom-fields').hidden=!open;$('#custom-toggle').setAttribute('aria-expanded',String(open));$('#custom-toggle').textContent=open?'− 收起自定义零件':'＋ 自己输入小零件';renderCustom()});$('#close-dialog').addEventListener('click',()=>$('#manual-copy').close());window.addEventListener('storage',e=>{if(e.key==='puppy-factory:favorites'||e.key===null){favorites=readFavorites(storage);renderSaved();renderGallery();renderFavorites()}});render();renderCustom();renderFilters();refreshGallery();showView('studio');
